import{_ as r,o as a,c as i,a3 as n}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Glossar","description":"Alle Begriffe aus ApptiveGrid kompakt erklärt.","frontmatter":{"title":"Glossar","description":"Alle Begriffe aus ApptiveGrid kompakt erklärt."},"headers":[],"relativePath":"referenz/glossar.md","filePath":"referenz/glossar.md","lastUpdated":1786434193000}'),t={name:"referenz/glossar.md"};function l(s,e,h,o,p,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="glossar" tabindex="-1">Glossar <a class="header-anchor" href="#glossar" aria-label="Permalink to &quot;Glossar&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#ansicht">Ansicht</a></li><li><a href="#apptivescript">ApptiveScript</a></li><li><a href="#ausloser">Auslöser</a></li><li><a href="#block">Block</a></li><li><a href="#durchlauf">Durchlauf</a></li><li><a href="#eintrag">Eintrag</a></li><li><a href="#feld">Feld</a></li><li><a href="#filter">Filter</a></li><li><a href="#flow">Flow</a></li><li><a href="#formular">Formular</a></li><li><a href="#grid">Grid</a></li><li><a href="#gruppierung">Gruppierung</a></li><li><a href="#link">Link</a></li><li><a href="#portal">Portal</a></li><li><a href="#rolle">Rolle</a></li><li><a href="#schritt">Schritt</a></li><li><a href="#seite">Seite</a></li><li><a href="#sitzplatz">Sitzplatz</a></li><li><a href="#space">Space</a></li><li><a href="#spaltentyp">Spaltentyp</a></li><li><a href="#testphase">Testphase</a></li><li><a href="#verknupfung">Verknüpfung</a></li><li><a href="#webhook">Webhook</a></li><li><a href="#begriffe-die-sie-ignorieren-konnen">Begriffe, die Sie ignorieren können</a></li></ul></nav><hr><h2 id="ansicht" tabindex="-1">Ansicht <a class="header-anchor" href="#ansicht" aria-label="Permalink to &quot;Ansicht&quot;">​</a></h2><p>Eine bestimmte Darstellung eines <a href="#grid">Grids</a>: welche Einträge sichtbar sind (Filter), in welcher Reihenfolge (Sortierung), wie gebündelt (Gruppierung) und welche Spalten erscheinen.</p><p>Eine Ansicht verändert die Daten nicht. Es gibt sieben Typen: Grid-Ansicht, Kanban, Kalender, Karte, Galerie, Liste, Timeline.</p><p>→ <a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></p><h2 id="apptivescript" tabindex="-1">ApptiveScript <a class="header-anchor" href="#apptivescript" aria-label="Permalink to &quot;ApptiveScript&quot;">​</a></h2><p>Die Ausdruckssprache von ApptiveGrid. Wird in Formelspalten, in der bedingten Block-Sichtbarkeit, in Flow-Bedingungen und in Filtern verwendet — jeder über die Oberfläche gebaute Filter <em>ist</em> ein ApptiveScript-Ausdruck. → <a href="/apptivescript/was-ist-apptivescript">Was ist ApptiveScript</a></p><h2 id="ausloser" tabindex="-1">Auslöser <a class="header-anchor" href="#ausloser" aria-label="Permalink to &quot;Auslöser&quot;">​</a></h2><p>Das Ereignis, das einen <a href="#flow">Flow</a> startet. Jeder Flow hat genau einen. → <a href="/flows/trigger">Trigger</a></p><h2 id="block" tabindex="-1">Block <a class="header-anchor" href="#block" aria-label="Permalink to &quot;Block&quot;">​</a></h2><p>Baustein einer <a href="#seite">Seite</a>: Text, Überschrift, Bild, Eingabefeld, eingebettete Ansicht, Auswertung oder Layout-Container. Blöcke können andere Blöcke enthalten.</p><p>→ <a href="/referenz/blocktypen">Blocktypen</a></p><h2 id="durchlauf" tabindex="-1">Durchlauf <a class="header-anchor" href="#durchlauf" aria-label="Permalink to &quot;Durchlauf&quot;">​</a></h2><p>Eine einzelne Ausführung eines <a href="#flow">Flows</a>. In der Oberfläche <em>Vorherige Ausführungen</em>. Jeder Durchlauf hat einen Status: <em>Fertig</em>, <em>Fehler</em> oder <em>Wartet</em>.</p><p>→ <a href="/flows/durchlaufhistorie">Durchlaufhistorie</a></p><h2 id="eintrag" tabindex="-1">Eintrag <a class="header-anchor" href="#eintrag" aria-label="Permalink to &quot;Eintrag&quot;">​</a></h2><p>Eine Zeile in einem <a href="#grid">Grid</a>. An einzelnen Stellen der Oberfläche auch <em>Entity</em> oder <em>Record</em> — gemeint ist dasselbe.</p><h2 id="feld" tabindex="-1">Feld <a class="header-anchor" href="#feld" aria-label="Permalink to &quot;Feld&quot;">​</a></h2><p>Eine Spalte eines <a href="#grid">Grids</a>. Jedes Feld hat einen <a href="#spaltentyp">Spaltentyp</a>. Die Begriffe <em>Feld</em> und <em>Spalte</em> meinen dasselbe.</p><p>→ <a href="/referenz/spaltentypen">Spaltentypen</a></p><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>Regel in einer <a href="#ansicht">Ansicht</a>, die bestimmt, welche Einträge sichtbar sind. Filter lassen sich mit <strong>und</strong>/<strong>oder</strong> gruppieren, maximal drei Ebenen tief.</p><p>Ein <strong>temporärer Filter</strong> gilt nur für Sie und nur in dieser Sitzung; ein gespeicherter Filter gilt für alle, die die Ansicht sehen.</p><p>→ <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2><p>Ein automatisierter Ablauf aus <a href="#schritt">Schritten</a>. Beginnt mit genau einem <a href="#auslöser">Auslöser</a>, danach folgen Aktionen und Helfer.</p><p>→ <a href="/flows/was-ist-ein-flow">Was ist ein Flow</a></p><h2 id="formular" tabindex="-1">Formular <a class="header-anchor" href="#formular" aria-label="Permalink to &quot;Formular&quot;">​</a></h2><p>Eine Eingabemaske auf ein <a href="#grid">Grid</a>. Kann neue Einträge anlegen oder bestehende bearbeiten. Ausfüllende brauchen kein ApptiveGrid-Konto, sofern der Zugriff nicht beschränkt ist.</p><p>→ <a href="/formulare/formular-erstellen">Formular erstellen</a></p><h2 id="grid" tabindex="-1">Grid <a class="header-anchor" href="#grid" aria-label="Permalink to &quot;Grid&quot;">​</a></h2><p>Eine Tabelle mit strukturierten Daten — der Datenspeicher. Jede Spalte hat einen festen Typ.</p><p>Nicht zu verwechseln mit der <a href="#ansicht">Ansicht</a>, die nur die Darstellung bestimmt.</p><p>→ <a href="/grids/grid-anlegen">Ihr erstes Grid</a></p><h2 id="gruppierung" tabindex="-1">Gruppierung <a class="header-anchor" href="#gruppierung" aria-label="Permalink to &quot;Gruppierung&quot;">​</a></h2><p>Bündelt Einträge einer <a href="#ansicht">Ansicht</a> nach den Werten eines Feldes. Je Gruppe lässt sich ein Aggregat einblenden: Summe, Durchschnitt, Minimum, Maximum, Gefüllt, Leer, Angehakt, Nicht angehakt.</p><h2 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to &quot;Link&quot;">​</a></h2><p>Eine extern teilbare Adresse. ApptiveGrid erzeugt Links für Formulare, Ansichten, <a href="#portal">Portale</a>, Flow-Starts und Einladungen.</p><p>Alle Links eines <a href="#space">Spaces</a> sind an einer Stelle gesammelt sichtbar.</p><p>→ <a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a></p><h2 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to &quot;Portal&quot;">​</a></h2><p>Eine veröffentlichte <a href="#seite">Seite</a> — erreichbar über einen Portal-Link, teilbar und in Websites einbettbar.</p><p>→ <a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></p><h2 id="rolle" tabindex="-1">Rolle <a class="header-anchor" href="#rolle" aria-label="Permalink to &quot;Rolle&quot;">​</a></h2><p>Bestimmt, was eine Person in einem <a href="#space">Space</a> darf. Vier Stufen: <strong>Eigentümer</strong>, <strong>Managen</strong>, <strong>Bearbeiten</strong>, <strong>Ansehen</strong>.</p><p>Nur <em>Ansehen</em> ist kostenfrei; die übrigen belegen einen <a href="#sitzplatz">Sitzplatz</a>.</p><p>→ <a href="/zusammenarbeit/rollen">Rollen</a></p><h2 id="schritt" tabindex="-1">Schritt <a class="header-anchor" href="#schritt" aria-label="Permalink to &quot;Schritt&quot;">​</a></h2><p>Ein einzelnes Element eines <a href="#flow">Flows</a>. Drei Arten: <strong>Auslöser</strong>, <strong>Aktionen</strong>, <strong>Helfer</strong>.</p><p>→ <a href="/flows/aktionen">Aktionen</a></p><h2 id="seite" tabindex="-1">Seite <a class="header-anchor" href="#seite" aria-label="Permalink to &quot;Seite&quot;">​</a></h2><p>Eine aus <a href="#block">Blöcken</a> zusammengesetzte Oberfläche. Veröffentlicht wird sie zum <a href="#portal">Portal</a>.</p><div class="warning custom-block"><p class="custom-block-title">Dreifach belegt</p><p>„Seite&quot; bezeichnet in der Oberfläche drei verschiedene Dinge:</p><ol><li><strong>Seite (Portal)</strong> — dieser Eintrag</li><li><strong>Formularseite</strong> — Abschnitt eines mehrseitigen Formulars</li><li><strong>Flow-Seite</strong> — eine Seite, die ein Flow-Schritt anzeigt</li></ol></div><p>→ <a href="/seiten/was-sind-seiten">Was sind Seiten</a></p><h2 id="sitzplatz" tabindex="-1">Sitzplatz <a class="header-anchor" href="#sitzplatz" aria-label="Permalink to &quot;Sitzplatz&quot;">​</a></h2><p>Eine Lizenz für eine Person mit Bearbeitungsrechten in einem <a href="#space">Space</a>. Leserechte sind kostenfrei und belegen keinen Platz.</p><p>→ <a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></p><h2 id="space" tabindex="-1">Space <a class="header-anchor" href="#space" aria-label="Permalink to &quot;Space&quot;">​</a></h2><p>Die oberste Organisationseinheit. Enthält Grids, Seiten und Flows. Zugriffsrechte, Tarif und Sitzplätze hängen am Space.</p><h2 id="spaltentyp" tabindex="-1">Spaltentyp <a class="header-anchor" href="#spaltentyp" aria-label="Permalink to &quot;Spaltentyp&quot;">​</a></h2><p>Legt fest, welche Werte ein <a href="#feld">Feld</a> aufnimmt, wie sie dargestellt und gefiltert werden und ob sie in Formularen abgefragt werden können.</p><p>Drei Typen berechnen ihren Wert selbst: <em>Wert übernehmen</em>, <em>Summe berechnen</em>, <em>Formel</em>.</p><p>→ <a href="/referenz/spaltentypen">Spaltentypen</a></p><h2 id="testphase" tabindex="-1">Testphase <a class="header-anchor" href="#testphase" aria-label="Permalink to &quot;Testphase&quot;">​</a></h2><p>Zeitraum nach Anlage eines <a href="#space">Spaces</a>, in dem erweiterte Funktionen zur Verfügung stehen. Die verbleibenden Tage stehen in den Space-Einstellungen.</p><h2 id="verknupfung" tabindex="-1">Verknüpfung <a class="header-anchor" href="#verknupfung" aria-label="Permalink to &quot;Verknüpfung&quot;">​</a></h2><p>Verbindung zwischen Einträgen zweier <a href="#grid">Grids</a>. Zwei Typen: <em>Eintrag verknüpfen</em> (ein Ziel) und <em>Mehrere Einträge verknüpfen</em> (mehrere Ziele).</p><p>Verknüpfungsketten über mehrere Grids sind nicht möglich.</p><p>→ <a href="/grids/verknuepfungen">Grids verknüpfen</a></p><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>Zwei Bedeutungen, je nach Richtung:</p><ul><li><strong>Ausgehend</strong> — eine Benachrichtigung, die ApptiveGrid bei einem Ereignis an ein fremdes System sendet. Konfiguriert in den Space-Einstellungen.</li><li><strong>Eingehend</strong> — ein Flow-Auslöser, über den ein fremdes System einen Flow startet.</li></ul><p>→ <a href="/integrationen/webhooks">Webhooks</a> · <a href="/flows/webhook-trigger">Flow per Webhook starten</a></p><hr><h2 id="begriffe-die-sie-ignorieren-konnen" tabindex="-1">Begriffe, die Sie ignorieren können <a class="header-anchor" href="#begriffe-die-sie-ignorieren-konnen" aria-label="Permalink to &quot;Begriffe, die Sie ignorieren können&quot;">​</a></h2><p>Diese tauchen an Randstellen der Oberfläche auf und sind für die tägliche Arbeit nicht nötig:</p><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td><em>VirtualGrid</em></td><td>Interner Name für <a href="#ansicht">Ansicht</a></td></tr><tr><td><em>Entity</em></td><td>Interner Name für <a href="#eintrag">Eintrag</a></td></tr><tr><td><em>Persistent Grid</em></td><td>Interner Name für <a href="#grid">Grid</a></td></tr><tr><td><em>Stable</em> / <em>Enterprise</em></td><td>Betriebsvarianten von ApptiveGrid</td></tr></tbody></table>',79)])])}const c=r(t,[["render",l]]);export{u as __pageData,c as default};
